<template><view class="insights">
 <view class="card insight-head"><view class="row between"><view><text class="eyebrow">小时的成长报告</text><text class="title">时间看得见，努力有回声。</text></view><CartoonArt kind="book" label="成长小册子"/></view><view class="segment"><button v-for="p in periods" :key="p.value" :class="{selected:period===p.value}" @click="period=p.value">{{p.label}}</button></view><view class="range-control"><button aria-label="上一周期" @click="shift(-1)">‹</button><button class="range-label" @click="dateOpen=true">{{rangeLabel}} ⌄</button><button aria-label="下一周期" :disabled="atCurrent" @click="shift(1)">›</button></view><button class="text-button back-today" @click="anchor=today">回到当前</button></view>
 <view v-if="loading" class="card muted">小时正在整理你的学习足迹…</view><view v-else-if="error" class="card"><text>{{error}}</text><button class="secondary small" @click="load">重新加载</button></view>
 <view v-else-if="report"><view class="metric-grid"><view class="metric honey"><text class="metric-label">专注时长</text><text class="metric-value">{{minutes(report.total_seconds)}}<text class="unit"> 分钟</text></text></view><view class="metric peach"><text class="metric-label">专注次数</text><text class="metric-value">{{report.count}}<text class="unit"> 次</text></text></view><view class="metric sage-soft"><text class="metric-label">最长一次专注</text><text class="metric-value">{{minutes(report.longest?.seconds||0)}}<text class="unit"> 分钟</text></text><text class="longest-task">{{report.longest?.task||'等你写下第一笔'}}</text></view><view v-if="period==='month'" class="metric blue-soft"><text class="metric-label">日均专注时长</text><text class="metric-value">{{minutes(report.average_seconds)}}<text class="unit"> 分钟</text></text><text class="longest-task">按本月已过去的 {{report.average_days}} 天计算</text></view></view>
 <view class="report-charts"><view class="card"><text class="title">{{periodTitle}}专注任务占比</text><SoftChart :items="pieItems" type="pie" label="任务专注时长占比环形图"/><view class="chart-legend"><view v-for="(task,i) in pieItems" :key="task.key" class="legend-row"><view class="legend-dot" :style="{background:colors[i%colors.length]}"/><text class="grow">{{task.title}}</text><text>{{minutes(task.seconds)}} 分 · {{(task.seconds/report.total_seconds*100).toFixed(1)}}%</text></view></view></view>
 <view v-if="period!=='month'" class="card"><text class="title">{{period==='day'?'专注时间段分布':'过去七天专注时长'}}</text><text class="muted">{{period==='day'?'北京时间 00:00–24:00 · 每小时专注分钟':'横轴：日期 · 纵轴：分钟'}}</text><SoftChart :items="period==='day'?report.hourly:report.daily" :type="period==='day'?'line':'bar'" :label="period==='day'?'每小时专注时长折线图':'每一天专注时长柱状图'"/><button class="text-button" @click="detailOpen=!detailOpen">{{detailOpen?'收起明细':'查看具体时长'}}</button><view v-if="detailOpen" class="distribution-detail"><text v-for="row in period==='day'?report.hourly:report.daily" :key="row.label">{{row.label}}　{{minutes(row.seconds)}} 分钟</text></view></view></view>
 <text class="report-note">按北京时间自然日统计已完成的专注；跨日时长分别计入对应日期，扣除暂停时间。{{report.approximate?'部分旧记录的时段按开始时间估算。':''}}</text>
 </view><DateSelect :open="dateOpen" :value="anchor" @select="selectDate" @close="dateOpen=false"/></view></template>
<script setup>
import {ref,computed,watch} from 'vue';import {onShow,onHide} from '@dcloudio/uni-app';import {store} from '../services/store';import {request,message} from '../services/api';import CartoonArt from './CartoonArt.vue';import SoftChart from './SoftChart.vue';import DateSelect from './DateSelect.vue';
const today=new Date(Date.now()+8*3600000).toISOString().slice(0,10),period=ref('day'),anchor=ref(today),report=ref(null),loading=ref(false),error=ref(''),dateOpen=ref(false),detailOpen=ref(false);let sequence=0;
const periods=[{value:'day',label:'日'},{value:'week',label:'近七天'},{value:'month',label:'月'}],colors=['#E8BE65','#E8AE93','#AFC3A2','#A6BEC9','#CAB5CA','#D5C293','#BFC5D7','#D1B49B'];
const periodTitle=computed(()=>period.value==='day'?'当日':period.value==='week'?'过去七天':'本月');
const minutes=s=>Number((s/60).toFixed(1));
const pieItems=computed(()=>{const rows=report.value?.tasks||[];return rows.length<=8?rows:[...rows.slice(0,7),{key:'other',title:'其他任务',seconds:rows.slice(7).reduce((n,r)=>n+r.seconds,0)}];});
const rangeLabel=computed(()=>period.value==='month'?anchor.value.slice(0,7).replace('-',' 年 ')+' 月':period.value==='week'&&report.value?.period==='week'?report.value.start+' ～ '+new Date(Date.parse(report.value.end)-86400000).toISOString().slice(0,10):anchor.value);
const atCurrent=computed(()=>period.value==='month'?anchor.value.slice(0,7)>=today.slice(0,7):anchor.value>=today);
function selectDate(value){if(value>today)return message('未来的努力，还等你来写。');anchor.value=value;}
function shift(delta){let d=new Date(anchor.value);if(period.value==='month'){d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+delta);}else d.setUTCDate(d.getUTCDate()+delta*(period.value==='week'?7:1));anchor.value=d.toISOString().slice(0,10)>today?today:d.toISOString().slice(0,10);}
async function load(){const n=++sequence;error.value='';report.value=null;if(!store.user)return;loading.value=true;try{const data=await request('/insights?period='+period.value+'&date='+anchor.value);if(n===sequence)report.value=data;}catch(e){if(n===sequence)error.value=e.message;}finally{if(n===sequence)loading.value=false;}}
watch([period,anchor,()=>store.user?.id],load,{immediate:true});onShow(load);onHide(()=>dateOpen.value=false);
</script>
<style scoped>.insight-head{background:#fff7df}.insight-head .title{font-size:30rpx}.range-control{display:flex;align-items:center;gap:8rpx;margin-top:20rpx}.range-control>button{background:#fff0c6;color:#7b5c30;font-size:35rpx;padding:9rpx 22rpx}.range-control .range-label{font-size:23rpx;flex:1;padding:18rpx 6rpx;background:#fffdf7}.back-today{margin:8rpx auto 0;font-size:22rpx}.metric-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18rpx;margin-bottom:26rpx}.metric{border-radius:24rpx;padding:28rpx 22rpx;border:2rpx solid #e6d6ae}.honey{background:#fff0bd}.peach{background:#fbe7d8}.sage-soft{background:#edf0dd}.blue-soft{background:#e9eff0}.metric-label{display:block;font-size:24rpx;color:#8c7048}.metric-value{display:block;color:#674d2d;font-weight:700;font-size:48rpx;margin:14rpx 0}.unit{font-weight:400;font-size:21rpx}.longest-task{font-size:22rpx;display:block;overflow-wrap:anywhere;color:#8b714c}.report-charts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22rpx}.report-charts>.card{min-width:0}.legend-row{display:flex;align-items:center;gap:12rpx;padding:11rpx 0;font-size:21rpx;color:#7b6443}.legend-row .grow{overflow-wrap:anywhere}.legend-dot{width:18rpx;height:18rpx;border-radius:6rpx;flex-shrink:0}.report-note{display:block;color:#a08b69;font-size:20rpx;line-height:1.8;margin-bottom:28rpx}.distribution-detail{display:grid;grid-template-columns:1fr 1fr;gap:10rpx;font-size:21rpx;color:#8c7048;margin-top:12rpx}@media(max-width:650px){.metric-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.metric:last-child:nth-child(3){grid-column:span 2}.report-charts{grid-template-columns:1fr;gap:0}.metric-value{font-size:44rpx}}
</style>
